400	/// Sortable id: `m`, 48 bits of milliseconds and 30 random bits in
401	/// lowercase Crockford base32 (17 characters).
402	fn new_id() -> String {
403	    const ALPHABET: &[u8; 32] = b"0123456789abcdefghjkmnpqrstvwxyz";
404	    let ms = std::time::SystemTime::now()
405	        .duration_since(std::time::UNIX_EPOCH)
406	        .map(|d| d.as_millis() as u64)
407	        .unwrap_or(0)
408	        & ((1 << 48) - 1);
409	    let mut rnd = [0u8; 4];
410	    let _ = getrandom::fill(&mut rnd);
411	    let v = (u128::from(ms) << 30) | u128::from(u32::from_le_bytes(rnd) & ((1 << 30) - 1));
412	    let mut out = String::with_capacity(17);
413	    out.push('m');
414	    for i in (0..16).rev() {
415	        out.push(ALPHABET[((v >> (i * 5)) & 31) as usize] as char);
416	    }
417	    out
418	}
