558	    /// Every version of a slot (or of the memory with this id), oldest first.
559	    pub fn history(
560	        &self,
561	        id: Option<&str>,
562	        subject: Option<&str>,
563	        key: Option<&str>,
564	        ns: Option<&str>,
565	    ) -> Result<Vec<MemoryRow>> {
566	        let (ns, subject_norm, key) = match (id, key) {
567	            (Some(id), _) => {
568	                let m = self.get(id)?.with_context(|| format!("no memory with id {id:?}"))?;
569	                match m.key.clone() {
570	                    Some(k) => {
571	                        (m.ns.clone(), m.subject.as_deref().map(normalize_name).unwrap_or_default(), k)
572	                    }
573	                    None => return Ok(vec![m]),
574	                }
575	            }
576	            (None, Some(k)) => {
577	                let ns = guard::namespace(ns.unwrap_or(&self.settings.namespace))?;
578	                let norm = match subject {
579	                    Some(s) => resolve_alias(&self.conn, &ns, &normalize_name(s))?,
580	                    None => String::new(),
581	                };
582	                (ns, norm, guard::key(k)?)
583	            }
584	            _ => bail!("pass a memory id, or --key (with --subject when the slot has one)"),
585	        };
586	        let mut stmt = self.conn.prepare_cached(&format!(
587	            "SELECT {COLUMNS} FROM memories WHERE ns = ?1 AND subject_norm = ?2 AND key = ?3 ORDER BY valid_from, rowid"
588	        ))?;
589	        Ok(stmt.query_map(params![ns, subject_norm, key], row)?.collect::<rusqlite::Result<_>>()?)
590	    }
