679	    /// Restore `export` output. Rows keep their ids and history; ids that
680	    /// already exist are skipped, so importing twice is harmless.
681	    pub fn import_jsonl(&mut self, input: impl BufRead) -> Result<ImportReport> {
682	        let mut report = ImportReport::default();
683	        let tx = self.write_tx()?;
684	        for (n, line) in input.lines().enumerate() {
685	            let line = line?;
686	            if line.trim().is_empty() {
687	                continue;
688	            }
689	            report.read += 1;
690	            let m: MemoryRow = match serde_json::from_str(&line) {
691	                Ok(m) => m,
692	                Err(err) => {
693	                    report.skipped += 1;
694	                    if report.errors.len() < 5 {
695	                        report.errors.push(format!("line {}: {err}", n + 1));
696	                    }
697	                    continue;
698	                }
699	            };
700	            if let Some(kind) =
701	                [Some(m.text.as_str()), m.subject.as_deref(), m.key.as_deref(), m.source.as_deref()]
702	                    .into_iter()
703	                    .flatten()
704	                    .find_map(secret_kind)
705	            {
706	                report.skipped += 1;
707	                if report.errors.len() < 5 {
708	                    report.errors.push(format!("line {}: refused, looks like a secret ({kind})", n + 1));
709	                }
710	                continue;
711	            }
712	            let exists: bool =
713	                tx.query_row("SELECT EXISTS (SELECT 1 FROM memories WHERE id = ?1)", [&m.id], |r| r.get(0))?;
714	            if exists {
715	                report.skipped += 1;
716	                continue;
717	            }
718	            if m.valid_to.is_none() && m.deleted_at.is_none() && m.key.is_some() {
719	                // A restored current value supersedes whatever holds its slot.
720	                let norm = m.subject.as_deref().map(normalize_name).unwrap_or_default();
721	                let replaced = tx.execute(
722	                    "UPDATE memories SET valid_to = ?4, superseded_by = ?5 WHERE ns = ?1 AND subject_norm = ?2 \
723	                     AND key = ?3 AND valid_to IS NULL AND deleted_at IS NULL",
724	                    params![m.ns, norm, m.key, m.valid_from, m.id],
725	                )?;
726	                report.replaced += replaced as u64;
727	            }
728	            if let Some(s) = &m.subject {
729	                ensure_subject(&tx, &m.ns, s, &normalize_name(s))?;
730	            }
731	            insert_row(&tx, &m)?;
732	            log(&tx, "import", Some(&m.id), &serde_json::to_value(&m)?)?;
733	            report.created += 1;
734	        }
735	        tx.commit()?;
736	        Ok(report)
737	    }
738	
739	    /// Bullets of a markdown memory file (`- ...`, `* ...`, `1. ...`) as
740	    /// notes, each about the nearest heading above it. Goes through the
741	    /// normal write path, so duplicates merge and secrets are refused.
742	    pub fn import_markdown(&mut self, text: &str, ns: Option<&str>, source: &str) -> Result<ImportReport> {
743	        let mut report = ImportReport::default();
744	        let mut heading: Option<String> = None;
745	        let mut fence: Option<&str> = None;
746	        let mut front_matter = text.trim_start().starts_with("---");
747	        for (n, line) in text.lines().enumerate() {
748	            let t = line.trim();
749	            if front_matter {
750	                front_matter = !(n > 0 && t == "---");
751	                continue;
752	            }
753	            if let Some(open) = fence {
754	                if t.starts_with(open) {
755	                    fence = None;
756	                }
757	                continue;
758	            }
759	            if let Some(open) = ["```", "~~~"].into_iter().find(|f| t.starts_with(f)) {
760	                fence = Some(open);
761	                continue;
762	            }
763	            if let Some(h) = t.strip_prefix('#') {
764	                let h = h.trim_start_matches('#').trim();
765	                heading = (!h.is_empty()).then(|| crate::text::truncate(h, 100));
766	                continue;
767	            }
768	            let item = t.strip_prefix("- ").or_else(|| t.strip_prefix("* ")).or_else(|| {
769	                t.split_once(". ").filter(|(n, _)| n.parse::<u32>().is_ok()).map(|(_, rest)| rest)
770	            });
771	            let Some(item) = item.map(|i| i.trim_start_matches("[ ] ").trim_start_matches("[x] ").trim())
772	            else {
773	                continue;
774	            };
775	            if item.is_empty() {
776	                continue;
777	            }
778	            report.read += 1;
779	            let req = Remember {
780	                text: crate::text::truncate(item, self.settings.max_chars),
781	                subject: heading.clone(),
782	                source: Some(source.to_string()),
783	                ns: ns.map(str::to_string),
784	                ..Default::default()
785	            };
786	            match self.remember(&req) {
787	                Ok(out) => match out.status {
788	                    WriteStatus::Created => report.created += 1,
789	                    WriteStatus::Replaced => report.replaced += 1,
790	                    WriteStatus::Duplicate => report.merged += 1,
791	                },
792	                Err(err) => {
793	                    report.skipped += 1;
794	                    if report.errors.len() < 5 {
795	                        report.errors.push(format!("{}: {err}", crate::text::truncate(item, 60)));
796	                    }
797	                }
798	            }
799	        }
800	        Ok(report)
801	    }
