803	    /// Expired rows are always dropped; the rest is opt-in.
804	    pub fn prune(&mut self, opts: PruneOptions) -> Result<PruneReport> {
805	        let now = now();
806	        let tx = self.write_tx()?;
807	        let mut report = PruneReport { dry_run: opts.dry_run, ..Default::default() };
808	        let run = |tx: &rusqlite::Transaction<'_>, sql: &str, args: &[&dyn rusqlite::ToSql]| -> Result<u64> {
809	            let count: i64 =
810	                tx.query_row(&format!("SELECT COUNT(*) FROM memories WHERE {sql}"), args, |r| r.get(0))?;
811	            if !opts.dry_run && count > 0 {
812	                tx.execute(&format!("DELETE FROM memories WHERE {sql}"), args)?;
813	            }
814	            Ok(count as u64)
815	        };
816	        report.expired = run(&tx, "deleted_at IS NULL AND valid_to IS NULL AND expires_at <= ?1", &[&now])?;
817	        if opts.forgotten {
818	            report.forgotten = run(&tx, "deleted_at IS NOT NULL", &[])?;
819	        }
820	        if opts.superseded {
821	            report.superseded = run(&tx, "valid_to IS NOT NULL AND deleted_at IS NULL", &[])?;
822	        }
823	        if let Some(days) = opts.unused_days {
824	            let cutoff = crate::text::format_unix(parse_unix(&now).unwrap_or(0) - i64::from(days) * 86_400);
825	            let sql = "deleted_at IS NULL AND valid_to IS NULL AND pinned = 0 AND importance <= 2 \
826	                       AND recall_count = 0 AND updated_at < ?1";
827	            let count: i64 =
828	                tx.query_row(&format!("SELECT COUNT(*) FROM memories WHERE {sql}"), [&cutoff], |r| r.get(0))?;
829	            if !opts.dry_run && count > 0 {
830	                tx.execute(
831	                    &format!("UPDATE memories SET deleted_at = ?2 WHERE {sql}"),
832	                    params![cutoff, now],
833	                )?;
834	            }
835	            report.unused = count as u64;
836	        }
837	        if !opts.dry_run {
838	            log(&tx, "prune", None, &serde_json::to_value(&report)?)?;
839	            tx.commit()?;
840	        }
841	        Ok(report)
842	    }
843	}
