882	        m.source,
883	        serde_json::to_string(&m.refs)?,
884	        m.pinned,
885	        m.created_at,
886	        m.updated_at,
887	        m.valid_from,
888	        m.valid_to,
889	        m.superseded_by,
890	        m.expires_at,
891	        m.deleted_at,
